-- SPH · Esquema relacional (3FN). Dialecto: PostgreSQL 15+. Compatible con SQLite tras reemplazar
-- "GENERATED BY DEFAULT AS IDENTITY" (ver tests/test_esquema_sql.py).
CREATE TABLE semestre (
  id_semestre   VARCHAR(6)  PRIMARY KEY,
  fecha_inicio  DATE        NOT NULL,
  fecha_fin     DATE        NOT NULL,
  CHECK (fecha_fin > fecha_inicio)
);
CREATE TABLE usuario (
  id_usuario INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  nombre     VARCHAR(100) NOT NULL,
  correo     VARCHAR(120) NOT NULL UNIQUE,
  rol        VARCHAR(20)  NOT NULL CHECK (rol IN ('COORDINADOR','CONSULTA','ADMIN'))
);
CREATE TABLE curso (
  id_curso VARCHAR(10)  PRIMARY KEY,
  nombre   VARCHAR(100) NOT NULL
);
CREATE TABLE grupo (
  id_grupo VARCHAR(12) PRIMARY KEY            -- cohorte, p. ej. 'SIS-3A'
);
CREATE TABLE dedicacion (
  id_dedicacion  SMALLINT    PRIMARY KEY,
  nombre         VARCHAR(30) NOT NULL UNIQUE,
  horas_maximas  SMALLINT    NOT NULL CHECK (horas_maximas > 0)
);
CREATE TABLE especialidad (
  id_especialidad SMALLINT   PRIMARY KEY,
  nombre          VARCHAR(60) NOT NULL UNIQUE
);
CREATE TABLE docente (
  id_docente      VARCHAR(10)  PRIMARY KEY,
  nombre          VARCHAR(100) NOT NULL,
  id_dedicacion   SMALLINT     NOT NULL REFERENCES dedicacion(id_dedicacion),
  id_especialidad SMALLINT     REFERENCES especialidad(id_especialidad)
);
CREATE TABLE disponibilidad_docente (
  id_disponibilidad INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_docente  VARCHAR(10) NOT NULL REFERENCES docente(id_docente) ON DELETE CASCADE,
  dia         SMALLINT NOT NULL CHECK (dia BETWEEN 1 AND 6),
  hora_inicio SMALLINT NOT NULL CHECK (hora_inicio BETWEEN 0 AND 23),
  hora_fin    SMALLINT NOT NULL CHECK (hora_fin BETWEEN 1 AND 24),
  CHECK (hora_fin > hora_inicio)
);
CREATE TABLE aula (
  id_aula    VARCHAR(10) PRIMARY KEY,
  nombre     VARCHAR(60) NOT NULL,
  capacidad  SMALLINT    NOT NULL CHECK (capacidad > 0),
  accesible  BOOLEAN     NOT NULL DEFAULT FALSE
);
CREATE TABLE tecnologia (
  id_tecnologia SMALLINT PRIMARY KEY,
  nombre        VARCHAR(40) NOT NULL UNIQUE
);
CREATE TABLE aula_tecnologia (
  id_aula       VARCHAR(10) NOT NULL REFERENCES aula(id_aula) ON DELETE CASCADE,
  id_tecnologia SMALLINT    NOT NULL REFERENCES tecnologia(id_tecnologia),
  PRIMARY KEY (id_aula, id_tecnologia)
);
CREATE TABLE oferta (
  id_oferta     INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_semestre   VARCHAR(6)  NOT NULL REFERENCES semestre(id_semestre),
  id_curso      VARCHAR(10) NOT NULL REFERENCES curso(id_curso),
  id_grupo      VARCHAR(12) NOT NULL REFERENCES grupo(id_grupo),
  cupo_esperado SMALLINT    NOT NULL CHECK (cupo_esperado > 0),
  UNIQUE (id_semestre, id_curso, id_grupo)
);
CREATE TABLE oferta_tecnologia (
  id_oferta     INTEGER  NOT NULL REFERENCES oferta(id_oferta) ON DELETE CASCADE,
  id_tecnologia SMALLINT NOT NULL REFERENCES tecnologia(id_tecnologia),
  PRIMARY KEY (id_oferta, id_tecnologia)
);
CREATE TABLE propuesta (
  id_propuesta        INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_semestre         VARCHAR(6) NOT NULL REFERENCES semestre(id_semestre),
  id_usuario          INTEGER    NOT NULL REFERENCES usuario(id_usuario),
  id_propuesta_origen INTEGER    REFERENCES propuesta(id_propuesta),   -- plantilla copiada (RF-03)
  nombre              VARCHAR(80) NOT NULL,
  estado              VARCHAR(12) NOT NULL DEFAULT 'BORRADOR' CHECK (estado IN ('BORRADOR','VALIDADA','APROBADA')),
  creada_en           TIMESTAMP   NOT NULL
);
CREATE TABLE sesion (
  id_sesion    INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_propuesta INTEGER     NOT NULL REFERENCES propuesta(id_propuesta) ON DELETE CASCADE,
  id_oferta    INTEGER     NOT NULL REFERENCES oferta(id_oferta),
  id_docente   VARCHAR(10) NOT NULL REFERENCES docente(id_docente),
  id_aula      VARCHAR(10) NOT NULL REFERENCES aula(id_aula),
  dia          SMALLINT    NOT NULL CHECK (dia BETWEEN 1 AND 6),
  hora_inicio  SMALLINT    NOT NULL CHECK (hora_inicio BETWEEN 0 AND 23),
  hora_fin     SMALLINT    NOT NULL CHECK (hora_fin BETWEEN 1 AND 24),
  CHECK (hora_fin > hora_inicio)
  -- Sin restricción de exclusión (docente/aula/grupo): la propuesta PUEDE contener conflictos;
  -- el sistema los detecta y recomienda, no los impide (RF de detección y recomendación).
);
CREATE INDEX ix_sesion_docente_dia ON sesion (id_propuesta, id_docente, dia);
CREATE INDEX ix_sesion_aula_dia    ON sesion (id_propuesta, id_aula, dia);
CREATE TABLE regla (
  id_regla    VARCHAR(6)  PRIMARY KEY,                   -- 'RD-01', 'RB-01', ...
  tipo        VARCHAR(6)  NOT NULL CHECK (tipo IN ('DURA','BLANDA')),
  nombre      VARCHAR(80) NOT NULL,
  descripcion TEXT        NOT NULL,
  activa      BOOLEAN     NOT NULL DEFAULT TRUE
);
CREATE TABLE parametro (
  id_parametro INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_regla     VARCHAR(6) REFERENCES regla(id_regla),     -- NULL = parámetro global
  id_semestre_desde VARCHAR(6) NOT NULL REFERENCES semestre(id_semestre),
  clave        VARCHAR(50) NOT NULL,
  valor        VARCHAR(40) NOT NULL,
  UNIQUE (id_regla, clave, id_semestre_desde)
);
CREATE TABLE cambio_sesion (
  id_cambio       INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  id_propuesta    INTEGER NOT NULL REFERENCES propuesta(id_propuesta) ON DELETE CASCADE,
  id_sesion       INTEGER NOT NULL REFERENCES sesion(id_sesion) ON DELETE CASCADE,
  id_usuario      INTEGER NOT NULL REFERENCES usuario(id_usuario),
  id_regla_origen VARCHAR(6) REFERENCES regla(id_regla),  -- conflicto que motivó el cambio
  origen          VARCHAR(12) NOT NULL CHECK (origen IN ('MANUAL','SUGERENCIA')),
  criterio        VARCHAR(40),
  dia_ant SMALLINT NOT NULL, hora_ini_ant SMALLINT NOT NULL, hora_fin_ant SMALLINT NOT NULL,
  id_aula_ant VARCHAR(10) NOT NULL REFERENCES aula(id_aula), id_docente_ant VARCHAR(10) NOT NULL REFERENCES docente(id_docente),
  dia_nue SMALLINT NOT NULL, hora_ini_nue SMALLINT NOT NULL, hora_fin_nue SMALLINT NOT NULL,
  id_aula_nue VARCHAR(10) NOT NULL REFERENCES aula(id_aula), id_docente_nue VARCHAR(10) NOT NULL REFERENCES docente(id_docente),
  realizado_en    TIMESTAMP NOT NULL
);
